@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800;900&display=swap');
:root{--bg:#101410;--panel:#171d18;--panel2:#1d241e;--line:#303830;--muted:#879087;--text:#f0f3ec;--lime:#d8ff3e;--mono:'DM Mono',monospace;--display:'Barlow Condensed','Space Grotesk',sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 76% 10%,#1b261a 0,transparent 34%),var(--bg);color:var(--text);font-family:'Space Grotesk',sans-serif;min-height:100vh}.app-shell{max-width:1450px;margin:auto;padding:0 56px}.topbar{height:76px;display:flex;align-items:center;border-bottom:1px solid #293028;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;color:#f6f7f3;text-decoration:none;font-size:19px;font-weight:700;letter-spacing:1.9px}.brand-mark{display:grid;place-items:center;width:27px;height:27px;background:var(--lime);color:#182012;font-family:var(--display);font-size:21px;font-weight:900;clip-path:polygon(25% 0,100% 0,100% 72%,72% 100%,0 100%,0 25%)}.brand-slash{color:var(--lime)}.season-tag,.eyebrow,.card-head,.track-label,.hud-caption,.lap-label,.speed-hud,.game-footer,.site-footer,.overlay-kicker,.overlay-foot,.event-pill small,.circuit-name>div>span,.stats-row>div>span,.difficulty small,.grid-count,.driver-number,.driver-rating,.challenge-overline,.challenge-progress,.sidebar-bottom{font-family:var(--mono);letter-spacing:.08em}.season-tag{color:#a7afa5;font-size:10px;display:flex;gap:12px;align-items:center}.live-dot,.online-status i{width:7px;height:7px;border-radius:50%;background:#c9f841;box-shadow:0 0 11px #c9f841;display:inline-block}.tag-divider{color:#535d51}.top-actions{display:flex;gap:20px;align-items:center}.icon-button{height:34px;width:34px;border:1px solid #343d33;background:transparent;color:#bec6b8;border-radius:50%;font-size:18px;cursor:pointer}.icon-button.muted{color:#70786f}.profile{display:flex;align-items:center;gap:10px;font-size:10px;letter-spacing:.12em;color:#c0c6bb}.profile-avatar{width:29px;height:29px;display:grid;place-items:center;border-radius:50%;background:#334333;color:var(--lime);font-size:9px;font-weight:600}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;padding:32px 0 22px}.eyebrow{font-size:9px;color:#9da69b;display:flex;gap:9px;align-items:center}.eyebrow-line{height:1px;width:22px;background:var(--lime)}h1{font-family:var(--display);font-size:55px;line-height:.9;letter-spacing:.015em;margin:10px 0 8px;font-weight:900}h1 span{color:var(--lime)}.subtitle{color:#899188;font-size:12px;margin:0}.event-pill{display:flex;align-items:center;gap:13px;border:1px solid #35402e;background:#171d15;padding:11px 15px;margin-bottom:3px}.event-icon{display:grid;place-items:center;width:29px;height:29px;background:#28311e;color:var(--lime);font-size:18px}.event-pill small{display:block;color:#8e998a;font-size:8px;margin-bottom:4px}.event-pill strong{font-family:var(--mono);font-size:11px;letter-spacing:.04em}.event-pill strong span{color:var(--lime);padding-left:9px}.race-layout{display:grid;grid-template-columns:minmax(0,1fr) 298px;gap:18px}.race-column{min-width:0}.game-frame{position:relative;overflow:hidden;border:1px solid #374036;background:#20291f;aspect-ratio:5/3;min-height:380px;max-height:600px;box-shadow:0 20px 70px #0005}.game-frame canvas{display:block;width:100%;height:100%;object-fit:fill}.game-frame:after{content:'';position:absolute;inset:0;pointer-events:none;border:1px solid #ffffff08;background:linear-gradient(180deg,#07100745 0%,transparent 23%,transparent 72%,#080d0877 100%)}.race-hud{position:absolute;z-index:2;top:21px;left:23px;right:23px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.race-hud[hidden],.speed-hud[hidden],.pause-overlay[hidden],.finish-overlay[hidden],.pause-button[hidden]{display:none}.lap-label{font-size:10px;color:#f4f6ed}.lap-label span:first-child{color:var(--lime);font-size:15px;font-weight:500;margin:0 4px}.lap-label i{font-style:normal;color:#818a7e;margin-right:4px}.lap-track{width:105px;height:3px;background:#ffffff35;margin-top:8px}.lap-track span{height:100%;width:0;display:block;background:var(--lime);transition:width .2s}.hud-center{text-align:center}.hud-caption{font-size:8px;color:#c6cbbd;display:block;margin-bottom:4px}.hud-center strong{font-family:var(--display);font-size:27px;line-height:1}.hud-center strong span{font-family:var(--mono);font-size:9px;color:var(--lime);margin-left:3px}.hud-right{text-align:right}.hud-right strong{font:12px var(--mono);letter-spacing:.06em}.speed-hud{z-index:2;position:absolute;bottom:23px;left:24px;display:flex;align-items:baseline;color:white;gap:6px}.speed-hud strong{font:700 29px var(--display);letter-spacing:.03em}.speed-hud>span:nth-child(2){font-size:8px;color:#c0c7ba}.speed-divider{height:21px;width:1px;background:#ffffff42;margin:0 9px;align-self:center}.speed-hud .boost-indicator{font-size:8px;color:#d4d8cc}.boost-indicator b{color:var(--lime);letter-spacing:2px;margin-left:4px}.track-label{position:absolute;bottom:25px;right:23px;z-index:2;color:#d4d9cc;font-size:8px}.track-label>span:nth-child(2){color:var(--lime);margin:0 7px}.track-label-dot{display:inline-block;width:5px;height:5px;background:var(--lime);border-radius:50%;margin-right:5px}.game-overlay,.pause-overlay,.finish-overlay{position:absolute;z-index:3;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;background:linear-gradient(90deg,#0d130fd9,#0d130f9c 50%,#0d130f8c);backdrop-filter:blur(1.3px)}.game-overlay:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#101711 0%,#101711dd 35%,transparent 75%);z-index:-1}.overlay-kicker{color:#bec6b7;font-size:9px;align-self:flex-start;margin:0 0 17px 9%;}.overlay-kicker span{color:var(--lime)}.game-overlay h2,.pause-overlay h2,.finish-overlay h2{font-family:var(--display);font-weight:900;font-size:58px;line-height:.84;text-align:left;letter-spacing:.015em;margin:0 0 16px;align-self:flex-start;margin-left:9%}.game-overlay h2 em{font-style:normal;color:var(--lime)}.game-overlay p,.pause-overlay p,.finish-overlay p{align-self:flex-start;margin:0 0 22px 9%;color:#a3aca0;font-size:11px}.start-button{align-self:flex-start;margin-left:9%;height:45px;padding:0 16px;background:var(--lime);border:0;color:#13190d;display:flex;align-items:center;gap:38px;cursor:pointer;font:500 10px var(--mono);letter-spacing:.04em;transition:background .15s,transform .15s}.start-button:hover{background:#e8ff80;transform:translateY(-2px)}.start-button b{font-size:17px;font-weight:400}.overlay-foot{align-self:flex-start;display:flex;gap:22px;color:#b1b8aa;font-size:8px;margin:36px 0 0 9%}.pause-button{position:absolute;right:20px;top:20px;z-index:5;width:34px;height:34px;border:1px solid #ffffff56;background:#141a13b8;color:#fff;cursor:pointer;font-size:11px}.pause-overlay,.finish-overlay{background:#101710c9}.pause-mark{font-size:25px;color:var(--lime);margin-bottom:13px}.pause-overlay h2,.finish-overlay h2{align-self:center;margin:0 0 11px;text-align:center;font-size:41px}.pause-overlay p,.finish-overlay p{align-self:center;margin:0 0 21px}.resume-button{background:var(--lime);border:0;padding:13px 18px;font:10px var(--mono);cursor:pointer}.resume-button span{margin-left:25px}.finish-badge{font:9px var(--mono);letter-spacing:.2em;color:var(--lime);border:1px solid #879e4a;padding:6px 10px;margin-bottom:16px}.finish-time{font:21px var(--mono);margin:0 0 18px}.replay-button{align-self:center;margin:0}.game-footer{height:43px;display:flex;align-items:center;border-bottom:1px solid #293028;color:#8e988c;font-size:8px;gap:7px}.game-footer kbd{font:9px var(--mono);color:#d8dfd1;background:#242c24;border:1px solid #3a4438;border-bottom-width:2px;padding:3px 5px;border-radius:2px}.control-tip>span{margin-right:5px}.control-tip i{width:1px;height:13px;background:#394137;display:inline-block;margin:0 8px -3px}.footer-note{margin-left:auto;color:#9aa68e}.footer-note span{color:var(--lime)}.fullscreen-button{border:0;background:none;color:#b7c0b1;font:8px var(--mono);margin-left:15px;cursor:pointer}.race-sidebar{display:flex;flex-direction:column;gap:12px}.side-card{border:1px solid #303a30;background:#171d18}.card-head{height:37px;border-bottom:1px solid #2c352c;padding:0 14px;display:flex;align-items:center;justify-content:space-between;color:#b6beb2;font-size:8px}.more-dots{letter-spacing:2px;color:#737e70}.circuit-art{height:137px;background:radial-gradient(ellipse at 50% 55%,#263622,#1a211a 66%);position:relative;overflow:hidden}.circuit-art:before,.circuit-art:after{content:'';position:absolute;width:3px;height:3px;border-radius:50%;background:#e5ff83;box-shadow:0 0 8px 3px #c5ff5180;left:15%;top:22%}.circuit-art:after{left:86%;top:70%;opacity:.5}.circuit-art svg{width:100%;height:100%;position:absolute;inset:0}.map-shadow{fill:none;stroke:#0d120d;stroke-width:11;stroke-linecap:round;stroke-linejoin:round}.map-line{fill:none;stroke:#a8e834;stroke-width:2;stroke-dasharray:3 2;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 0 4px #a8e8a9)}.map-start{fill:#fff;stroke:#bfff40;stroke-width:4;filter:drop-shadow(0 0 4px #bfff40)}.map-arrow{fill:#b9fa49}.map-coordinate{position:absolute;bottom:10px;left:14px;color:#74806d;font:7px var(--mono);letter-spacing:.1em}.circuit-name{display:flex;justify-content:space-between;align-items:center;padding:11px 14px 13px}.circuit-name h3{margin:0 0 4px;font-size:15px;font-weight:600}.circuit-name>div>span{font-size:7px;color:#8d978a}.difficulty{text-align:right}.difficulty i{font:8px var(--mono);color:var(--lime);letter-spacing:2px;display:block}.difficulty small{font-size:6px;color:#899386}.stats-row{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #303a30;padding:11px 13px}.stats-row>div{border-right:1px solid #303a30;padding-left:9px}.stats-row>div:first-child{padding-left:0}.stats-row>div:last-child{border:0}.stats-row>div>span{font-size:6px;color:#879083;display:block;margin-bottom:6px}.stats-row strong{font:11px var(--mono);white-space:nowrap}.stats-row strong small{font-size:7px;color:#9da697;font-weight:400}.grid-card .card-head{height:37px}.grid-count{font-size:7px;color:#859081}.driver-row{height:39px;display:flex;align-items:center;padding:0 13px;border-bottom:1px solid #252d25;gap:10px}.driver-row:last-child{border:0}.driver-number{font-size:8px;color:#667163;width:17px}.driver-color{width:7px;height:18px;background:var(--lime);border-radius:1px}.pink-color{background:#fc618e}.yellow-color{background:#f6c844}.blue-color{background:#62a8ff}.driver-name{font-size:9px;font-weight:600;letter-spacing:.07em;flex:1}.driver-name small{font:7px var(--mono);color:#7b8679;margin-left:4px}.driver-rating{color:#a3ad9c;font-size:8px}.player-row .driver-rating{color:var(--lime)}.challenge-card{min-height:96px;border:1px solid #465332;background:linear-gradient(120deg,#26301f,#1d241a);padding:13px 13px;position:relative;display:flex;gap:11px}.challenge-icon{color:var(--lime);font-size:20px}.challenge-overline{display:block;color:#aab392;font-size:7px;margin:1px 0 5px}.challenge-card strong{font-size:11px}.challenge-card p{color:#909a89;font-size:8px;margin:4px 0}.challenge-progress{position:absolute;right:13px;top:15px;font-size:7px;color:#b8c2ad}.challenge-progress i{width:41px;height:2px;background:#536046;display:inline-block;margin:0 0 2px 6px}.sidebar-bottom{margin-top:auto;display:flex;justify-content:space-between;color:#63705f;font-size:6px;padding:3px 2px}.sidebar-bottom b{color:var(--lime)}.site-footer{height:57px;display:flex;align-items:center;justify-content:space-between;color:#677264;font-size:7px}.site-footer>div{display:flex;gap:22px}.online-status{color:#7e897a}.online-status i{width:5px;height:5px;margin-right:5px}.site-footer>span:first-child{letter-spacing:.08em}
@media(max-width:1050px){.app-shell{padding:0 28px}.race-layout{grid-template-columns:minmax(0,1fr) 260px;gap:12px}.event-card .stats-row{padding-left:9px;padding-right:9px}.stats-row>div{padding-left:6px}.stats-row strong{font-size:10px}.footer-note{display:none}}
@media(max-width:760px){.app-shell{padding:0 15px}.topbar{height:62px}.season-tag{display:none}.page-heading{padding:25px 0 18px;align-items:center}.page-heading h1{font-size:48px}.subtitle{font-size:10px;max-width:220px;line-height:1.5}.event-pill{padding:8px 9px;gap:7px}.event-pill strong{font-size:8px}.event-pill small{font-size:6px}.event-icon{width:23px;height:23px}.race-layout{display:flex;flex-direction:column}.race-sidebar{display:grid;grid-template-columns:1fr 1fr}.side-card.event-card{grid-row:span 2}.challenge-card{min-height:90px}.sidebar-bottom{grid-column:1/-1}.game-frame{min-height:310px;aspect-ratio:1.5}.game-overlay h2{font-size:45px}.game-overlay p{font-size:9px;max-width:240px;text-align:left}.overlay-foot{font-size:7px;gap:12px;margin-top:22px}.start-button{height:40px;font-size:8px}.game-footer{height:38px}.fullscreen-button{display:none}.site-footer{font-size:6px}.site-footer>div{gap:10px}.site-footer>span:last-child{display:none}}
@media(max-width:520px){.profile-name{display:none}.page-heading{align-items:flex-end}.event-pill{margin-bottom:4px}.race-sidebar{display:flex}.race-sidebar .event-card{order:0}.game-frame{min-height:340px;aspect-ratio:1.15}.game-frame canvas{object-fit:cover}.game-overlay{align-items:flex-start;padding-left:6%}.overlay-kicker,.game-overlay h2,.game-overlay p,.start-button,.overlay-foot{margin-left:0}.game-overlay h2{font-size:43px}.overlay-foot{flex-direction:column;gap:7px}.track-label{font-size:7px;right:12px;bottom:19px}.speed-hud{left:13px;bottom:18px}.race-hud{left:14px;right:14px;top:14px}.control-tip{display:flex;align-items:center;gap:3px}.control-tip>span{margin-right:2px}.control-tip kbd{font-size:7px;padding:3px}.control-tip i{margin:0 4px -3px}.game-footer{font-size:7px}.site-footer{justify-content:center}.site-footer>div{display:none}}

(() => {
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const startOverlay = $('startOverlay');
  const pauseOverlay = $('pauseOverlay');
  const finishOverlay = $('finishOverlay');
  const raceHud = $('raceHud');
  const speedHud = $('speedHud');
  const pauseButton = $('pauseButton');
  const TAU = Math.PI * 2;
  const START_T = Math.PI / 2;
  const ROAD_HALF = 61;
  const cars = [];
  const keys = new Set();
  let state = 'ready';
  let lastFrame = 0;
  let elapsed = 0;
  let lap = 0;
  let previousProgress = 0;
  let currentProgress = 0;
  let speed = 0;
  let heading = 0;
  let boost = 1;
  let usedBrake = false;
  let finishTimeout = 0;
  let audioOn = true;
  const track = (t) => ({
    x: 500 + 320 * Math.cos(t) + 18 * Math.cos(3 * t),
    y: 300 + 204 * Math.sin(t) + 12 * Math.sin(3 * t)
  });
  const tangent = (t) => {
    const p = track(t), q = track(t + .001);
    return Math.atan2(q.y - p.y, q.x - p.x);
  };
  const trackPoints = Array.from({ length: 480 }, (_, i) => track(i / 480 * TAU));
  const scenery = [];
  let seed = 8941;
  const random = () => { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; };
  for (let i = 0; i < 145; i++) {
    const a = random() * TAU;
    const r = random() < .72 ? 1 : .62;
    scenery.push({ x: 500 + (320 * r + 95 + random() * 110) * Math.cos(a), y: 300 + (204 * r + 82 + random() * 90) * Math.sin(a), size: 3 + random() * 7, shade: Math.floor(random() * 4) });
  }
  const carSpecs = [
    { name: 'YOU', color: '#d8ff3e', stripe: '#efffa7', player: true, offset: 0 },
    { name: 'NOVA', color: '#fb5f8c', stripe: '#ffc0d1', offset: -.11, pace: .00035 },
    { name: 'KAI', color: '#f4c842', stripe: '#fff0a0', offset: -.22, pace: .00031 },
    { name: 'MILES', color: '#62a8ff', stripe: '#c4e0ff', offset: -.33, pace: .00029 }
  ];
  function freshRace() {
    cars.length = 0;
    carSpecs.forEach((spec, i) => {
      const t = START_T + .18 + spec.offset;
      const p = track(t);
      cars.push({ ...spec, x: p.x, y: p.y + (i ? (i % 2 ? 17 : -17) : 0), angle: tangent(t), t, progress: 0, speed: 0, laps: 0, color: spec.color });
    });
    lap = 0; elapsed = 0; speed = 0; boost = 1; usedBrake = false;
    previousProgress = 0; currentProgress = .18;
    $('lapCurrent').textContent = '1'; $('lapTotal').textContent = '3'; $('lapFill').style.width = '3%';
    $('timer').textContent = '00:00.00'; $('speed').textContent = '000'; $('position').innerHTML = '1<span>ST</span>';
    $('boostLabel').innerHTML = 'BOOST <b>▰▰▰</b>';
  }
  freshRace();

  function drawBackground() {
    const bg = ctx.createLinearGradient(0, 0, 1000, 600);
    bg.addColorStop(0, '#29372b'); bg.addColorStop(.48, '#344432'); bg.addColorStop(1, '#202d23');
    ctx.fillStyle = bg; ctx.fillRect(0, 0, 1000, 600);
    // Subtle ground grain and softly lit city blocks beyond the course.
    for (let i = 0; i < 70; i++) {
      const x = (i * 193 + 37) % 1000, y = (i * 317 + 18) % 600;
      ctx.fillStyle = i % 3 ? '#ffffff05' : '#0b160b12'; ctx.fillRect(x, y, 35 + (i % 5) * 9, 2);
    }
    ctx.save();
    for (let i = 0; i < 17; i++) {
      const x = i * 73 - 12, h = 22 + (i * 41 % 49);
      ctx.fillStyle = '#111a17'; ctx.fillRect(x, 0, 54, h);
      ctx.fillRect(x + 4, 600 - h * .7, 48, h * .7);
      for (let wy = 9; wy < h - 5; wy += 10) for (let wx = 7; wx < 49; wx += 13) {
        ctx.fillStyle = (i + wx + wy) % 4 === 0 ? '#eaff7b35' : '#a9c5a00c'; ctx.fillRect(x + wx, wy, 3, 3);
      }
    }
    ctx.restore();
    // Infield lawn, subtly patterned like a compact street circuit park.
    ctx.fillStyle = '#35482f'; ctx.beginPath(); ctx.ellipse(500, 300, 234, 133, -.04, 0, TAU); ctx.fill();
    ctx.save(); ctx.beginPath(); ctx.ellipse(500, 300, 228, 128, -.04, 0, TAU); ctx.clip();
    for (let x = 285; x < 730; x += 24) { ctx.fillStyle = (x / 24 | 0) % 2 ? '#ffffff04' : '#12201109'; ctx.fillRect(x, 150, 8, 300); }
    ctx.restore();
    // Outer run-off and asphalt ribbon.
    strokeTrack('#111812', 153);
    strokeTrack('#7c856c', 147);
    ctx.save(); ctx.lineWidth = 141; ctx.setLineDash([12, 12]); ctx.lineDashOffset = 0; ctx.strokeStyle = '#e5c862'; pathTrack(); ctx.stroke(); ctx.setLineDash([12, 12]); ctx.lineDashOffset = 12; ctx.strokeStyle = '#f1f0dc'; pathTrack(); ctx.stroke(); ctx.restore();
    strokeTrack('#282d2c', 126);
    // Directional asphalt texture.
    ctx.save(); ctx.lineWidth = 1; ctx.strokeStyle = '#ffffff08'; pathTrack(); ctx.stroke();
    ctx.setLineDash([17, 18]); ctx.lineDashOffset = 0; ctx.lineWidth = 2; ctx.strokeStyle = '#e7e7cf91'; pathTrack(); ctx.stroke(); ctx.restore();
    // Start line, placed across the road at the bottom of the circuit.
    const start = track(START_T), startAngle = tangent(START_T) + Math.PI / 2;
    ctx.save(); ctx.translate(start.x, start.y); ctx.rotate(startAngle);
    for (let i = 0; i < 12; i++) { ctx.fillStyle = i % 2 ? '#eef0e5' : '#202522'; ctx.fillRect(-6 + i * 12, -5, 12, 10); }
    ctx.restore();
    // Landscape lights, planted trees and a low-contrast inner service road.
    scenery.forEach((tree, i) => {
      ctx.fillStyle = '#0e160f33'; ctx.beginPath(); ctx.ellipse(tree.x + 3, tree.y + 5, tree.size * 1.1, tree.size * .62, -.3, 0, TAU); ctx.fill();
      ctx.fillStyle = ['#435c3e', '#506b43', '#3d5539', '#63794b'][tree.shade];
      ctx.beginPath(); ctx.arc(tree.x, tree.y, tree.size, 0, TAU); ctx.fill();
      ctx.fillStyle = '#a1bd6950'; ctx.beginPath(); ctx.arc(tree.x - tree.size * .25, tree.y - tree.size * .3, tree.size * .47, 0, TAU); ctx.fill();
      if (i % 5 === 0) { ctx.fillStyle = '#d7fa7a'; ctx.shadowColor = '#d7fa7a'; ctx.shadowBlur = 12; ctx.beginPath(); ctx.arc(tree.x, tree.y, 1.5, 0, TAU); ctx.fill(); ctx.shadowBlur = 0; }
    });
    // A little infield pit building gives the circuit a sense of place.
    ctx.fillStyle = '#263126'; ctx.fillRect(431, 278, 139, 23); ctx.fillStyle = '#475241'; ctx.fillRect(439, 282, 123, 14);
    ctx.fillStyle = '#bce447'; ctx.fillRect(447, 285, 2, 8); ctx.fillRect(454, 285, 2, 8); ctx.fillRect(461, 285, 2, 8);
    ctx.fillStyle = '#202820'; ctx.font = '7px monospace'; ctx.fillText('PIT  /  NEON CIRCUIT', 474, 292);
  }
  function pathTrack() {
    ctx.beginPath();
    trackPoints.forEach((p, i) => i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y));
    ctx.closePath();
  }
  function strokeTrack(color, width) { ctx.save(); ctx.lineWidth = width; ctx.strokeStyle = color; ctx.lineJoin = 'round'; ctx.lineCap = 'round'; pathTrack(); ctx.stroke(); ctx.restore(); }

  function drawCar(car, isPlayer) {
    ctx.save(); ctx.translate(car.x, car.y); ctx.rotate(car.angle);
    // Shadow and tire-contact shadow.
    ctx.fillStyle = '#0508058a'; ctx.beginPath(); ctx.ellipse(2, 5, 17, 10, 0, 0, TAU); ctx.fill();
    // Rear lights glow as the cars sweep around the bends.
    ctx.fillStyle = '#ff465b'; ctx.shadowColor = '#ff314c'; ctx.shadowBlur = 9; ctx.fillRect(-13, -7, 3, 4); ctx.fillRect(-13, 3, 3, 4); ctx.shadowBlur = 0;
    // Wheels.
    ctx.fillStyle = '#111413';
    for (const x of [-9, 7]) { ctx.fillRect(x, -10, 7, 3); ctx.fillRect(x, 7, 7, 3); }
    // Sculpted compact racer silhouette.
    ctx.fillStyle = car.color; ctx.beginPath();
