    ctx.fillStyle = '#fff6ce'; ctx.shadowColor = '#efffc4'; ctx.shadowBlur = 7; ctx.fillRect(12, -5, 3, 2); ctx.fillRect(12, 3, 3, 2); ctx.shadowBlur = 0;
