    $('lapFill').style.width = `${Math.max(1, progress / TAU * 100)}%`;
    $('timer').textContent = formatTime(elapsed);
    $('speed').textContent = String(Math.round(speed * 49)).padStart(3, '0');
    $('boostLabel').innerHTML = `BOOST <b>${boost > .66 ? '▰▰▰' : boost > .33 ? '▰▰' : boost > .04 ? '▰' : '···'}</b>`;
