    $('position').innerHTML = `${place}<span>${suffix}</span>`;
    document.querySelectorAll('.driver-row').forEach((row, i) => row.querySelector('.driver-rating').textContent = `P${standing.findIndex(c => c.i === i) + 1}`);
  }
